proc stepEncLcnRsInstance*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnRsInstance](src)
  var n = 6
  if x.failure.isSome:
    inc n
  if x.intent_revision.isSome:
    inc n
  if x.origin.isSome:
    inc n
  if x.provider.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.failure.isSome:
    node.entries[k].key = cbor("failure")
    w.later(stepEncLcnRsFailure, addr x.failure.get, addr node.entries[k].value)
    inc k
  node.entries[k].key = cbor("instance")
  node.entries[k].value = cbor(x.instance)
  inc k
  node.entries[k].key = cbor("intent")
  w.later(stepEncLcnRsInstanceIntentChoice, addr x.intent, addr node.entries[k].value)
  inc k
  if x.intent_revision.isSome:
    node.entries[k].key = cbor("intent_revision")
    node.entries[k].value = cbor(uint64(x.intent_revision.get))
    inc k
  if x.origin.isSome:
    node.entries[k].key = cbor("origin")
    w.later(stepEncLcnRsOrigin, addr x.origin.get, addr node.entries[k].value)
    inc k
  if x.provider.isSome:
    node.entries[k].key = cbor("provider")
    node.entries[k].value = cbor(x.provider.get)
    inc k
  node.entries[k].key = cbor("record")
  w.later(stepEncLcnRsRecord, addr x.record, addr node.entries[k].value)
  inc k
  node.entries[k].key = cbor("revision")
  node.entries[k].value = cbor(uint64(x.revision))
  inc k
  node.entries[k].key = cbor("source")
  w.later(stepEncLcnRsInstanceSourceChoice, addr x.source, addr node.entries[k].value)
  inc k
  node.entries[k].key = cbor("state")
  w.later(stepEncLcnRsInstanceStateChoice, addr x.state, addr node.entries[k].value)
  inc k

proc stepDecLcnRsInstance*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnRsInstance](dst)
  r[] = LcnRsInstance()
  let f3 = v.lookup("failure")
  if f3.isSome:
    r.failure = Opt.some(default(LcnRsFailure))
    w.later(stepDecLcnRsFailure, f3.get, addr r.failure.get)
  r.instance = v.lookup("instance").get.text
  let f4 = v.lookup("intent").get
  w.later(stepDecLcnRsInstanceIntentChoice, f4, addr r.intent)
  let f5 = v.lookup("intent_revision")
  if f5.isSome:
    r.intent_revision = Opt.some(uint64(f5.get.uint))
  let f6 = v.lookup("origin")
  if f6.isSome:
    r.origin = Opt.some(default(LcnRsOrigin))
    w.later(stepDecLcnRsOrigin, f6.get, addr r.origin.get)
  let f7 = v.lookup("provider")
  if f7.isSome:
    r.provider = Opt.some(f7.get.text)
  let f8 = v.lookup("record").get
  w.later(stepDecLcnRsRecord, f8, addr r.record)
  r.revision = uint64(v.lookup("revision").get.uint)
  let f9 = v.lookup("source").get
  w.later(stepDecLcnRsInstanceSourceChoice, f9, addr r.source)
  let f10 = v.lookup("state").get
  w.later(stepDecLcnRsInstanceStateChoice, f10, addr r.state)

proc toCbor*(x: LcnRsInstance): CborValue =
  runEnc(stepEncLcnRsInstance, addr x)

proc fromChecked*(T: type LcnRsInstance, v: CborValue): LcnRsInstance =
  var r: LcnRsInstance
  runDec(stepDecLcnRsInstance, v, addr r)
  r

